{
  "type": "object",
  "properties": {
    "old_dates": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^\\d{2}-\\d{2}-\\d{4}$"
      },
      "description": "Danh sách các ngày dặn đón hiện tại trong đơn (trước khi sửa). Định dạng dd-MM-yyyy. Dùng để xác định những ngày nào sẽ bị thay đổi"
    },
    "dates": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^\\d{2}-\\d{2}-\\d{4}$"
      },
      "description": "Danh sách ngày mà người đón sẽ đến đón học sinh. Theo định dạng dd-MM-yyyy. (nếu có thay đổi)"
    },
    "full_name": {
      "type": "string",
      "description": "Tên của người đón (nếu có thay đổi)"
    },
    "phone": {
      "type": "string",
      "pattern": "^(03|05|07|08|09)",
      "description": "Số điện thoại người đón"
    },
    "images": {
      "type": "array",
      "items": {
        "type": "string",
        "format": "uri"
      },
      "minItems": 1,
      "description": "Bắt buộc phải lấy toàn bộ và chỉ những LINK mới được đính sau [Image sent].(nếu có thay đổi)"
    },
    "relationship": {
      "type": "string",
      "description": "Mối quan hệ của người đón với học sinh (ví dụ: bố, mẹ, ông, bà, cô, chú...). Trường này không bắt buộc, không hỏi thêm, chỉ extract nếu có."
    }
  },
  "required": ["old_dates"]
}

