tools_dev.parameters:
{
  "type": "object",
  "properties": {
    "dates": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^\\d{2}-\\d{2}-\\d{4}$"
      },
      "description": "Danh sách ngày cần tạo ticket, định dạng dd-MM-yyyy"
    },
    "type_ticket": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "leave_request_ticket",
          "medication_instruction_ticket",
          "pickup_instruction_ticket"
        ]
      },
      "description": "Loại ticket cần lấy thông tin. Gồm có:\n- leave_request_ticket: đơn xin nghỉ học\n- medication_instruction_ticket: đơn dặn uống thuốc\n- pickup_instruction_ticket: đơn dặn đón học sinh"
    },
	"status": {
        "type": "string",
        "enum": ["pending", "approved"],
        "description": "Trạng thái đơn cần lấy. Không chỉ rõ thì lấy cả hai"
      }
  },
  "required": ["type_ticket", "dates"]
}

