tools_dev.parameters:
{
  "type": "object",
  "properties": {
    "dates": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^\\d{2}-\\d{2}-\\d{4}$"
      },
      "description": "Danh sách các ngày cần lấy thông tin, định dạng dd-MM-yyyy"
    },
    "fields": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": ["learning", "eating", "sleeping", "hygiene"]
      },
      "description": "Danh sách lĩnh vực muốn truy vấn (nếu không truyền thì lấy tất cả)"
    }
  },
  "required": ["dates"]
}

{
  "type": "object",
  "properties": {
    "from_date": {
      "type": "string",
      "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
      "description": "Ngày bắt đầu, định dạng dd-MM-yyyy."
    },
    "to_date": {
      "type": "string",
      "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
      "description": "Ngày kết thúc, định dạng dd-MM-yyyy."
    },
    "type_ticket": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "leave_request_ticket",
          "medication_instruction_ticket",
          "pickup_instruction_ticket"
        ]
      },
      "description": "Loại ticket cần lấy thông tin."
    },
    "status": {
      "type": "string",
      "enum": ["pending", "approved"],
      "description": "Trạng thái đơn cần lấy. Nếu không chỉ rõ thì lấy cả hai."
    }
  },
  "required": ["type_ticket", "from_date", "to_date"]
}

{
  "type": "object",
  "properties": {
    "quarter": {
      "type": "integer",
      "enum": [1, 2, 3, 4],
      "description": "Quý cần thống kê: 1, 2, 3 hoặc 4."
    },
    "year": {
      "type": "integer",
      "minimum": 2000,
      "description": "Năm cần thống kê, ví dụ: 2025"
    },
    "type_ticket": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "leave_request_ticket",
          "medication_instruction_ticket",
          "pickup_instruction_ticket"
        ]
      },
      "description": "Loại ticket cần lấy thông tin."
    },
    "status": {
      "type": "string",
      "enum": ["pending", "approved"],
      "description": "Trạng thái đơn cần lấy. Nếu không chỉ rõ thì lấy cả hai."
    }
  },
  "required": ["type_ticket", "quarter", "year"]
}

{
  "type": "object",
  "properties": {
    "type_action": {
      "type": "string",
      "enum": ["create", "update", "delete"],
      "description": "Hành động: create, update hoặc delete."
    },
    "create_info": {
      "type": "object",
      "properties": {
        "dates": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
            "description": "Ngày nghỉ muốn tạo, định dạng dd-mm-yyyy."
          }
        }
      },
      "required": ["dates"],
      "description": "Thông tin đơn nghỉ mới cần tạo."
    },
    "delete_info": {
      "type": "object",
      "properties": {
        "dates": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
            "description": "Ngày nghỉ muốn hủy, định dạng dd-mm-yyyy."
          }
        }
      },
      "required": ["dates"],
      "description": "Thông tin đơn nghỉ cần hủy."
    },
    "update_info": {
      "type": "object",
      "properties": {
        "is_update_date": {
          "type": "boolean",
          "description": "True nếu người dùng muốn thay đổi ngày nghỉ, False nếu không."
        },
        "date_changes": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "old_date": {
                "type": "string",
                "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
                "description": "Ngày nghỉ cũ cần sửa. (bắt buộc)"
              },
              "new_date": {
                "type": "string",
                "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
                "description": "Ngày nghỉ mới muốn đổi sang (nếu có)."
              }
            },
            "required": ["old_date"]
          },
          "description": "Danh sách thay đổi ngày. Chỉ cần old_date nếu chưa biết new_date."
        }
      },
      "required": ["is_update_date"],
      "description": "Thông tin đơn nghỉ cần cập nhật."
    }
  },
  "required": ["type_action"]
}

