{
  "type": "object",
  "properties": {
    "type_action": {
      "type": "string",
      "enum": ["create", "update", "delete"],
      "description": "Hành động: create, update hoặc delete."
    },
    "create_info": {
      "type": "object",
      "properties": {
        "dates": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
            "description": "Ngày dặn thuốc cần tạo, định dạng dd-mm-yyyy."
          }
        }
      },
      "required": ["dates"],
      "description": "Thông tin đơn dặn thuốc mới cần tạo."
    },
    "delete_info": {
      "type": "object",
      "properties": {
        "dates": {
          "type": "array",
          "items": {
            "type": "string",
            "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
            "description": "Ngày dặn thuốc cần hủy, định dạng dd-mm-yyyy."
          }
        }
      },
      "required": ["dates"],
      "description": "Thông tin đơn dặn thuốc cần hủy."
    },
    "update_info": {
      "type": "object",
      "properties": {
        "is_update_date": {
          "type": "boolean",
          "description": "True nếu người dùng muốn thay đổi ngày dặn thuốc, False nếu không."
        },
        "date_changes": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "old_date": {
                "type": "string",
                "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
                "description": "Ngày dặn thuốc cũ cần sửa. (Bắt buộc)"
              },
              "new_date": {
                "type": "string",
                "pattern": "^\\d{2}-\\d{2}-\\d{4}$",
                "description": "Ngày dặn thuốc mới muốn đổi sang (nếu có)."
              }
            },
            "required": ["old_date"]
          },
          "description": "Danh sách thay đổi ngày. Chỉ cần old_date nếu chưa biết new_date."
        }
      },
      "required": ["is_update_date"],
      "description": "Thông tin đơn dặn thuốc cần cập nhật."
    }
  },
  "required": ["type_action"]
}

