def filter_medicine_requests(context):
    list_date = context.get('combine_date', [])
    leave_requests = context.get("list_medicine_tickets", [])
    result_dict = {}

    for item in leave_requests:
        leave_date = item.get("medicationDate")
        status = item.get("status", "").lower()

        if leave_date in list_date and status == "approved":
            if leave_date not in result_dict:
                result_dict[leave_date] = {
                    "note": "đơn đã approve không thể bổ sung thông tin dặn thuốc được, hãy liên hệ trực tiếp với giáo viên"
                }

    return result_dict


