def check_has_past_dates(date_list, start_date_str, number_of_days, date_format="%d-%m-%Y"):
    """Kiểm tra ngày trong quá khứ, ngày hiện tại trước 10:30 (UTC+7), và ngày cách quá 1 tháng, trả về conclusions"""

    # Lấy thời gian hiện tại ở múi giờ UTC+7
    now = datetime.datetime.now() + datetime.timedelta(hours=7)
    today = now.date()
    current_time = now.time()
    morning_deadline = datetime.time(10, 30)  # Đổi từ 7:30 -> 10:30
    number_of_days = number_of_days

    has_past_date = False
    past_dates = []
    valid_dates = []
    has_today = False
    has_far_date = False
    far_dates = []
    conclusions = []

    dates_to_check = []

    if date_list:
        for date_str in date_list:
            try:
                d = datetime.datetime.strptime(date_str, date_format).date()
                dates_to_check.append(d)
            except ValueError:
                continue  # Bỏ qua ngày không đúng định dạng
    elif start_date_str and number_of_days:
        try:
            start_date = datetime.datetime.strptime(start_date_str, date_format).date()
        except ValueError:
            raise ValueError("start_leave_datetime phải có định dạng DD-MM-YYYY")

        for i in range(number_of_days):
            dates_to_check.append(start_date + datetime.timedelta(days=i))
    else:
        raise ValueError("Thiếu thông tin: cần 'dates' hoặc 'start_leave_datetime' + 'number_of_days'.")

    for d in dates_to_check:
        date_str = d.strftime(date_format)
        if d < today:
            has_past_date = True
            past_dates.append(date_str)
        elif d == today:
            has_today = True
            if current_time < morning_deadline:
                valid_dates.append(date_str)  # Chỉ thêm ngày hiện tại nếu trước 10:30
        else:
            # Kiểm tra ngày cách quá 1 tháng (30 ngày)
            delta_days = (d - today).days
            if delta_days > 30:
                has_far_date = True
                far_dates.append(date_str)
            else:
                valid_dates.append(date_str)  # Ngày tương lai trong vòng 30 ngày

    # Tạo conclusions dựa trên điều kiện
    if has_past_date:
        conclusions.append({
            "message": f"theo quy định không xin nghỉ được cho ngày đã qua.",
        })

    if has_today and current_time >= morning_deadline:
        conclusions.append({
            "message": f"theo quy định sau 10:30 sáng muốn xin nghỉ thì phải liện hệ với nhà trường theo số hotline.",
        })

    if has_far_date:
        conclusions.append({
            "message": f"Không báo nghỉ trước 1 tháng để đảm bảo thông tin chính xác và nhà trường có thể sắp xếp hợp lý. Đây cũng là quy định nhà trường"
        })

    return conclusions

date_list = context['combine_date']
start_date_str = context['parameters'].get("start_leave_datetime")
number_of_days = context['parameters'].get("number_of_days", 1)
result_after_check = check_has_past_dates(date_list, start_date_str, number_of_days)
has_warning = False
if result_after_check:   
    has_warning = True

# Tạo kết quả
result = {
    "has_warning": has_warning,
    "conclusions": result_after_check  # Sửa từ conclusions thành result_after_check
}

def check_has_past_dates(date_list, date_format="%d-%m-%Y"):
    """Kiểm tra ngày trong quá khứ, ngày hiện tại trước 16:30 (UTC+7), và ngày cách quá 2 tuần, trả về conclusions"""

    # Lấy thời gian hiện tại ở múi giờ UTC+7
    now = datetime.datetime.now() + datetime.timedelta(hours=7)
    today = now.date()
    current_time = now.time()
    afternoon_deadline = datetime.time(16, 30)  # Đổi từ 9:00 sang 16:30

    has_past_date = False
    past_dates = []
    valid_dates = []
    has_today = False
    has_far_date = False
    far_dates = []
    conclusions = []

    dates_to_check = []

    if date_list:
        for date_str in date_list:
            try:
                d = datetime.datetime.strptime(date_str, date_format).date()
                dates_to_check.append(d)
            except ValueError:
                continue  # Bỏ qua ngày không đúng định dạng
    else:
        raise ValueError("Thiếu thông tin: cần 'dates'")

    for d in dates_to_check:
        date_str = d.strftime(date_format)
        if d < today:
            has_past_date = True
            past_dates.append(date_str)
        elif d == today:
            has_today = True
            if current_time < afternoon_deadline:
                valid_dates.append(date_str)  # Chỉ thêm ngày hiện tại nếu trước 16:30
        else:
            # Kiểm tra ngày cách quá 2 tuần
            delta_days = (d - today).days
            if delta_days > 14:
                has_far_date = True
                far_dates.append(date_str)
            else:
                valid_dates.append(date_str)  # Ngày tương lai trong vòng 2 tuần

    # Tạo conclusions dựa trên điều kiện
    if has_past_date:
        conclusions.append({
            "message": f"theo quy định không dặn thuốc cho ngày đã qua.",
        })

    if has_today and current_time >= afternoon_deadline:
        conclusions.append({
            "message": f"theo quy định sau 16:30 chiều muốn dặn thuốc thì phải liện hệ với nhà trường theo số hotline.",
        })

    if has_far_date:
        conclusions.append({
            "message": f"Để đảm bảo an toàn và đúng hướng dẫn, không nên dặn thuốc trước quá 2 tuần. Đây cũng là quy định của nhà trường"
        })

    return conclusions

date_list = context['combine_date']
result_after_check = check_has_past_dates(date_list)
has_warning = False
if result_after_check:  
    has_warning = True

result = {
    "has_warning": has_warning,
    "conclusions": result_after_check  # Sửa từ conclusions thành result_after_check
}

def check_next_action(type_action, is_update_date, date_changes, tickets_data):
    now_utc = datetime.datetime.utcnow()
    now = now_utc + datetime.timedelta(hours=7)
    cutoff_time = now.replace(hour=10, minute=30, second=0, microsecond=0)

    def format_day_month(date_str):
        try:
            return datetime.datetime.strptime(date_str, "%d-%m-%Y").strftime("%d-%m")
        except:
            return date_str

    def validate_new_date(new_date_str, now_utc7):
        try:
            new_date = datetime.datetime.strptime(new_date_str, "%d-%m-%Y").date()
        except Exception:
            return f"Ngày {new_date_str}: Định dạng ngày không hợp lệ"

        today = now_utc7.date()

        # Kiểm tra ngày quá khứ
        if new_date < today:
