def check_has_past_dates(date_list, date_format="%d-%m-%Y"):
    """Kiểm tra ngày trong quá khứ, ngày hiện tại trước 16:30 (UTC+7), và ngày cách quá 1 tháng, trả về conclusions"""

    # Lấy thời gian hiện tại ở múi giờ UTC+7
    now = datetime.datetime.now() + datetime.timedelta(hours=7)
    today = now.date()
    current_time = now.time()
    afternoon_deadline = datetime.time(16, 30)

    has_past_date = False
    past_dates = []
    valid_dates = []
    has_today = False
    has_far_date = False
    far_dates = []
    conclusions = []

    dates_to_check = []

    if date_list:
        for date_str in date_list:
            try:
                d = datetime.datetime.strptime(date_str, date_format).date()
                dates_to_check.append(d)
            except ValueError:
                continue  # Bỏ qua ngày không đúng định dạng
    else:
        raise ValueError("Thiếu thông tin: cần 'dates'")

    for d in dates_to_check:
        date_str = d.strftime(date_format)
        if d < today:
            has_past_date = True
            past_dates.append(date_str)
        elif d == today:
            has_today = True
            if current_time < afternoon_deadline:
                valid_dates.append(date_str)  # Chỉ thêm ngày hiện tại nếu trước 16:30
        else:
            # Kiểm tra ngày cách quá 2 tuần (14 ngày)
            delta_days = (d - today).days
            if delta_days > 14:
                has_far_date = True
                far_dates.append(date_str)
            else:
                valid_dates.append(date_str)  # Ngày tương lai trong vòng 2 tuần

    # Tạo conclusions dựa trên điều kiện
    if has_past_date:
        conclusions.append({
            "message": f"theo quy định không dặn đón cho ngày đã qua.",
        })
    if has_today and current_time >= afternoon_deadline:
        conclusions.append({
            "message": f"theo quy định sau 16:30 chiều muốn dặn đón thì phải liện hệ với nhà trường theo số hotline.",
        })

    if has_far_date:
        conclusions.append({
            "message": f"để đảm bảo thông tin chính xác và thuận tiện cho sắp xếp, phụ huynh không nên dặn đón trẻ trước quá 2 tuần. Đây cũng là quy định của nhà trường"
        })

    return conclusions

