    if type_action == "create":
        return {
            "next_action": "Gọi luôn tool create_pickup_ticket",
            "note": "Bắt buộc show ra ngày định dạng dd-mm trong câu trả lời (không phải dạng dd-mm-yyyy)"
        }

    # Nếu type_action là update và update_target có giá trị, trong đó update_target chứa 'date'
    if type_action == "update" and is_update_date:
        return {
            "next_action": "edit_submitted_ticket_pickup"
        }

    # Trường hợp còn lại
    return {
        "note": "Hiện chưa có đơn nào"
    }

result = should_continue_next_action(context)
